// Generated by AI

using UnityEngine;

public class AccessibilityManager : MonoBehaviour
{
    [Header("HUD Contrast")]
    [SerializeField] private GameObject hudNormal;
    [SerializeField] private GameObject hudHigh;
    [SerializeField] private GameObject hudVeryHigh;

    [Header("Contrast Selection")]
    [SerializeField] private GameObject contrastNormalGreen;
    [SerializeField] private GameObject contrastHighGreen;
    [SerializeField] private GameObject contrastVeryHighGreen;

    [Header("Subtitle System")]
    [SerializeField] private SubtitleController subtitleController;

    [Header("Text Size Selection")]
    [SerializeField] private GameObject textSmallGreen;
    [SerializeField] private GameObject textMediumGreen;
    [SerializeField] private GameObject textLargeGreen;

    [Header("Mini-game Speed Selection")]
    [SerializeField] private GameObject speedSlowGreen;
    [SerializeField] private GameObject speedMediumGreen;
    [SerializeField] private GameObject speedFastGreen;

    [Header("Player Controller")]
    [SerializeField] private PlayerController playerController;


    // Configuration values
    private static readonly int[] TextSizes = { 14, 18, 22 };

    private static readonly float[] PlayerSpeeds = { 4f, 5f, 6f };


    private void Start()
    {
        SettingsManager settings = SettingsManager.Instance;

        int contrastIndex = 0;
        int textSizeIndex = 1;
        int speedIndex = 1;

        if (settings != null)
        {
            // Recover the current session configuration
            contrastIndex = settings.HudContrastIndex;
            textSizeIndex = settings.SubtitleTextSizeIndex;
            speedIndex = settings.PlayerSpeedIndex;
        }
        else
        {
            Debug.LogError(
                "AccessibilityManager: SettingsManager was not found."
            );
        }

        // Apply settings without modifying the stored preferences
        ApplyContrast(contrastIndex);
        ApplyTextSize(textSizeIndex);
        ApplySpeed(speedIndex);
    }


    // CONTRAST

    public void SetNormalContrast()
    {
        ChangeContrast(0);
    }


    public void SetHighContrast()
    {
        ChangeContrast(1);
    }


    public void SetVeryHighContrast()
    {
        ChangeContrast(2);
    }


    private void ChangeContrast(int index)
    {
        ApplyContrast(index);

        SettingsManager.Instance?.SetHudContrastIndex(index);
    }


    private void ApplyContrast(int index)
    {
        index = Mathf.Clamp(index, 0, 2);

        SetObjectActive(hudNormal, index == 0);
        SetObjectActive(hudHigh, index == 1);
        SetObjectActive(hudVeryHigh, index == 2);

        SetObjectActive(contrastNormalGreen, index == 0);
        SetObjectActive(contrastHighGreen, index == 1);
        SetObjectActive(contrastVeryHighGreen, index == 2);
    }


    // TEXT SIZE

    public void SelectSmallText()
    {
        ChangeTextSize(0);
    }


    public void SelectMediumText()
    {
        ChangeTextSize(1);
    }


    public void SelectLargeText()
    {
        ChangeTextSize(2);
    }


    private void ChangeTextSize(int index)
    {
        ApplyTextSize(index);

        SettingsManager.Instance?.SetSubtitleTextSizeIndex(index);
    }


    private void ApplyTextSize(int index)
    {
        index = Mathf.Clamp(index, 0, 2);

        SetObjectActive(textSmallGreen, index == 0);
        SetObjectActive(textMediumGreen, index == 1);
        SetObjectActive(textLargeGreen, index == 2);

        if (subtitleController != null)
        {
            subtitleController.SetTextSize(TextSizes[index]);
        }
    }


    // MINI-GAME SPEED

    public void SelectSlowSpeed()
    {
        ChangeSpeed(0);
    }


    public void SelectMediumSpeed()
    {
        ChangeSpeed(1);
    }


    public void SelectFastSpeed()
    {
        ChangeSpeed(2);
    }


    private void ChangeSpeed(int index)
    {
        ApplySpeed(index);

        SettingsManager.Instance?.SetPlayerSpeedIndex(index);
    }


    private void ApplySpeed(int index)
    {
        index = Mathf.Clamp(index, 0, 2);

        SetObjectActive(speedSlowGreen, index == 0);
        SetObjectActive(speedMediumGreen, index == 1);
        SetObjectActive(speedFastGreen, index == 2);

        if (playerController != null)
        {
            playerController.SetMoveSpeed(PlayerSpeeds[index]);
        }
    }


    // GENERAL UTILITY

    private void SetObjectActive(GameObject target, bool active)
    {
        if (target != null)
        {
            target.SetActive(active);
        }
    }
}
